const { execFileSync } = require('node:child_process');
const { writeFileSync } = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '../..');
const git = args => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const metadata = { commit: git(['rev-parse', '--short=7', 'HEAD']), message: git(['log', '-1', '--pretty=%s']) };
writeFileSync(path.join(root, 'src/core/releaseMetadata.ts'),
  `// Generated by the release workflow before uploading the application bundle.\nexport const releaseMetadata: {commit: string; message: string} = ${JSON.stringify(metadata)};\n`);
console.log(`Recorded release metadata for ${metadata.commit}.`);
